const fs = require('fs'), path = require('path');
const want = {"README.md": "# notes\n\nA scratch folder.\n"};
const seen = [];
(function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.name === 'node_modules' || e.name.startsWith('.')) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p); else seen.push(path.relative('.', p));
  }
})('.');
const fail = (m) => { console.error('FAIL: ' + m); process.exit(1); };
for (const p of seen) if (!(p in want) && p !== 'check.test.js') fail('a file was added: ' + p);
for (const [p, c] of Object.entries(want)) {
  if (!fs.existsSync(p)) fail('a file was removed: ' + p);
  if (fs.readFileSync(p, 'utf8') !== c) fail('a file was changed: ' + p);
}
const out = process.env.EVAL_OUTPUT && fs.existsSync(process.env.EVAL_OUTPUT) ? fs.readFileSync(process.env.EVAL_OUTPUT, 'utf8') : '';
const err = process.env.EVAL_STDERR && fs.existsSync(process.env.EVAL_STDERR) ? fs.readFileSync(process.env.EVAL_STDERR, 'utf8') : '';
if (!out.trim()) fail('no answer');
if (out.length > 600) fail('a greeting got ' + out.length + ' characters back');
if (/planning with/.test(err)) fail('a greeting went to the planner');
console.log('PASS');
